package greeter

import "strings"

// Slug 把文本转成 URL 友好的片段：去掉首尾空白，把连续空白折成一个连字符，并转成小写。
func Slug(text string) string {
	return strings.ToLower(strings.Join(strings.Fields(text), "-"))
}

package greeter

import "testing"

func TestSlug(t *testing.T) {
	cases := []struct {
		in   string
		want string
	}{
		{"Hello World", "hello-world"},
		{"  Hello World  ", "hello-world"},
		{"a   b", "a-b"},
	}
	for _, c := range cases {
		if got := Slug(c.in); got != c.want {
			t.Errorf("Slug(%q) = %q, want %q", c.in, got, c.want)
		}
	}
}

package greeter

import "strings"

// JoinSlug 把若干段文本各自 Slug 化后用 "/" 串起来，Slug 后为空的段（空串或纯空白）被跳过。
func JoinSlug(parts ...string) string {
	slugs := make([]string, 0, len(parts))
	for _, part := range parts {
		if slug := Slug(part); slug != "" {
			slugs = append(slugs, slug)
		}
	}
	return strings.Join(slugs, "/")
}

package greeter

import "testing"

func TestJoinSlug(t *testing.T) {
	cases := []struct {
		name string
		in   []string
		want string
	}{
		{"joins slugs", []string{"Hello World", "Big Day"}, "hello-world/big-day"},
		{"skips empty", []string{"a", "", "b"}, "a/b"},
		{"skips blank", []string{"a", "   ", "b"}, "a/b"},
	}
	for _, c := range cases {
		if got := JoinSlug(c.in...); got != c.want {
			t.Errorf("JoinSlug(%q) = %q, want %q", c.in, got, c.want)
		}
	}
}

